446	def wrap_handle_tensordesc(launcher):
447	    def inner(*args):
448	        # 9 is the metadata arguments in `args` defined in `make_launcher`
449	        meta_args = args[:9]
450	        raw_kernel_args = args[9:]
451	        final_args = []
452	        for i, arg in enumerate(raw_kernel_args):
453	            if isinstance(arg, TensorDescriptor):
454	                final_args.extend(make_tensordesc_arg(arg))
455	            elif isinstance(arg, tuple):
456	                final_args.append(_expand_tensordesc_tuple(arg))
457	            else:
458	                final_args.append(arg)
459	        return launcher(*meta_args, *final_args)
460	
461	    return inner
