239	static PyObject *loadBinary(PyObject *self, PyObject *args) {
240	  const char *name;
241	  const char *data;
242	  Py_ssize_t data_size;
243	  int shared;
244	  int device;
245	  if (!PyArg_ParseTuple(args, "ss#ii", &name, &data, &data_size, &shared,
246	                        &device)) {
247	    return NULL;
248	  }
249	  CUfunction fun;
250	  CUmodule mod;
251	  int32_t n_regs = 0;
252	  int32_t n_spills = 0;
253	  int32_t n_max_threads = 0;
254	  // create driver handles
255	  CUcontext pctx = 0;
256	
257	  Py_BEGIN_ALLOW_THREADS;
258	  CUDA_CHECK_AND_RETURN_NULL_ALLOW_THREADS(cuCtxGetCurrent(&pctx));
259	  if (!pctx) {
260	    CUDA_CHECK_AND_RETURN_NULL_ALLOW_THREADS(
261	        cuDevicePrimaryCtxRetain(&pctx, device));
262	    CUDA_CHECK_AND_RETURN_NULL_ALLOW_THREADS(cuCtxSetCurrent(pctx));
263	  }
264	
265	  CUDA_CHECK_AND_RETURN_NULL_ALLOW_THREADS(cuModuleLoadData(&mod, data));
266	  CUDA_CHECK_AND_RETURN_NULL_ALLOW_THREADS(
267	      cuModuleGetFunction(&fun, mod, name));
268	  // get allocated registers and spilled registers from the function
269	  CUDA_CHECK_AND_RETURN_NULL_ALLOW_THREADS(
270	      cuFuncGetAttribute(&n_regs, CU_FUNC_ATTRIBUTE_NUM_REGS, fun));
271	  CUDA_CHECK_AND_RETURN_NULL_ALLOW_THREADS(
272	      cuFuncGetAttribute(&n_spills, CU_FUNC_ATTRIBUTE_LOCAL_SIZE_BYTES, fun));
273	  n_spills /= 4;
274	  CUDA_CHECK_AND_RETURN_NULL_ALLOW_THREADS(cuFuncGetAttribute(
275	      &n_max_threads, CU_FUNC_ATTRIBUTE_MAX_THREADS_PER_BLOCK, fun));
276	  // set dynamic shared memory if necessary
277	  int shared_optin;
278	  CUDA_CHECK_AND_RETURN_NULL_ALLOW_THREADS(cuDeviceGetAttribute(
279	      &shared_optin, CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN,
280	      device));
281	  if (shared > 49152 && shared_optin > 49152) {
282	    CUDA_CHECK_AND_RETURN_NULL_ALLOW_THREADS(
283	        cuFuncSetCacheConfig(fun, CU_FUNC_CACHE_PREFER_SHARED));
284	    int shared_total, shared_static;
285	    CUDA_CHECK_AND_RETURN_NULL_ALLOW_THREADS(cuDeviceGetAttribute(
286	        &shared_total, CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_MULTIPROCESSOR,
287	        device));
288	    CUDA_CHECK_AND_RETURN_NULL_ALLOW_THREADS(cuFuncGetAttribute(
289	        &shared_static, CU_FUNC_ATTRIBUTE_SHARED_SIZE_BYTES, fun));
290	    CUDA_CHECK_AND_RETURN_NULL_ALLOW_THREADS(
291	        cuFuncSetAttribute(fun, CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES,
292	                           shared_optin - shared_static));
293	  }
294	  Py_END_ALLOW_THREADS;
295	
296	  if (PyErr_Occurred()) {
297	    return NULL;
298	  }
299	  return Py_BuildValue("(KKiii)", (uint64_t)mod, (uint64_t)fun, n_regs,
300	                       n_spills, n_max_threads);
301	}
