439	        cuDevicePrimaryCtxRetain(&ctx, /*device=*/0));
440	    CUDA_CHECK_AND_RETURN_NULL_ALLOW_THREADS(cuCtxSetCurrent(ctx));
441	  }
442	
443	  // We can't set the fifo size after running a kernel that calls printf.  This
444	  // is true even if the set() call is a nop and the new size is the same as the
445	  // old size.
446	  //
