931	static void _launch(int gridX, int gridY, int gridZ, int num_warps,
932	                    int num_ctas, int launch_cooperative_grid, int launch_pdl,
933	                    int shared_memory, CUstream stream, CUfunction function,
934	                    void **params) {
935	  if (gridX * gridY * gridZ > 0) {
936	    // 4 attributes that we can currently pass maximum
937	    CUlaunchAttribute launchAttr[4];
938	    static cuLaunchKernelEx_t cuLaunchKernelExHandle = NULL;
939	    if (cuLaunchKernelExHandle == NULL) {
940	      cuLaunchKernelExHandle = getLaunchKernelExHandle();
941	    }
942	    CUlaunchConfig config;
943	    config.gridDimX = gridX * num_ctas;
944	    config.gridDimY = gridY;
945	    config.gridDimZ = gridZ;
946	
947	    config.blockDimX = 32 * num_warps;
948	    config.blockDimY = 1;
949	    config.blockDimZ = 1;
950	    config.sharedMemBytes = shared_memory;
951	    config.hStream = stream;
952	    config.attrs = launchAttr;
953	    int num_attrs = 0;
954	
955	    if (launch_pdl != 0) {
956	      CUlaunchAttribute pdlAttr = {
957	          .id = CU_LAUNCH_ATTRIBUTE_PROGRAMMATIC_STREAM_SERIALIZATION,
958	          .value = 1};
959	      launchAttr[num_attrs] = pdlAttr;
960	      ++num_attrs;
961	    }
962	
963	    if (launch_cooperative_grid != 0) {
964	      CUlaunchAttribute coopAttr = {.id = CU_LAUNCH_ATTRIBUTE_COOPERATIVE,
965	                                    .value = 1};
966	      launchAttr[num_attrs] = coopAttr;
967	      ++num_attrs;
968	    }
969	
970	    if (num_ctas != 1) {
971	      CUlaunchAttribute clusterAttr = {};
972	      clusterAttr.id = CU_LAUNCH_ATTRIBUTE_CLUSTER_DIMENSION;
973	      clusterAttr.value.clusterDim.x = num_ctas;
974	      clusterAttr.value.clusterDim.y = 1;
975	      clusterAttr.value.clusterDim.z = 1;
976	      launchAttr[num_attrs] = clusterAttr;
977	      ++num_attrs;
978	
979	      CUlaunchAttribute clusterSchedulingAttr = {};
980	      clusterSchedulingAttr.id =
981	          CU_LAUNCH_ATTRIBUTE_CLUSTER_SCHEDULING_POLICY_PREFERENCE;
982	      clusterSchedulingAttr.value.clusterSchedulingPolicyPreference =
983	          CU_CLUSTER_SCHEDULING_POLICY_SPREAD;
984	      launchAttr[num_attrs] = clusterSchedulingAttr;
985	      ++num_attrs;
986	    }
987	
988	    // num_ctas == 16 is non-portable. Does work for H100 and B200 tho
989	    config.numAttrs = num_attrs;
990	    if (num_ctas == 16) {
991	      CUDA_CHECK(cuFuncSetAttribute(
992	          function, CU_FUNC_ATTRIBUTE_NON_PORTABLE_CLUSTER_SIZE_ALLOWED, 1));
993	    }
994	
995	    CUDA_CHECK(cuLaunchKernelExHandle(&config, function, params, 0));
996	  }
997	}
