1001	// Extract a CUDA device pointer from a pointer-like PyObject obj, and store
1002	// it to the memory location pointed by ptr.
1003	bool extractPointer(void *ptr, PyObject *obj) {
1004	  CUdeviceptr *dev_ptr = ptr;
1005	  if (obj == Py_None) {
1006	    *dev_ptr = (CUdeviceptr)0; // valid nullptr
1007	    return true;
1008	  }
1009	  if (PyLong_Check(obj)) {
1010	    *dev_ptr = PyLong_AsUnsignedLongLong(obj);
1011	    return true;
1012	  }
1013	  PyObject *ret = PyObject_CallMethodNoArgs(obj, data_ptr_str);
1014	  if (!ret) {
1015	    PyErr_SetString(
1016	        PyExc_TypeError,
1017	        "Pointer argument must be either uint64 or have data_ptr method");
1018	    return false;
1019	  }
1020	  if (!PyLong_Check(ret)) {
1021	    PyErr_SetString(PyExc_TypeError,
1022	                    "data_ptr method of Pointer object must return 64-bit int");
1023	    return false;
1024	  }
1025	  *dev_ptr = PyLong_AsUnsignedLongLong(ret);
1026	  Py_DECREF(ret);
1027	  if (*dev_ptr == 0) {
1028	    return true; // valid nullptr
1029	  }
1030	  CUresult status = cuPointerGetAttribute(
1031	      dev_ptr, CU_POINTER_ATTRIBUTE_DEVICE_POINTER, *dev_ptr);
1032	  if (status == CUDA_ERROR_INVALID_VALUE) {
1033	    PyErr_Format(PyExc_ValueError,
1034	                 "Pointer argument cannot be accessed from Triton "
1035	                 "(cpu tensor?)");
1036	    return false;
1037	  }
1038	  return gpuAssert(status, __FILE__, __LINE__);
1039	}
