1116	// Extract a CUtensorMap descriptor from a python object, and store it to the
1117	// memory location pointed by ptr.
1118	bool extractTmaDesc(void *ptr, PyObject *obj) {
1119	  if (sizeof(CUtensorMap *) != 8) {
1120	    PyErr_SetString(PyExc_SystemError,
1121	                    "getTmaDesc() requires 64-bit compilation");
1122	    return false;
1123	  }
1124	  if (Py_TYPE(obj) != &PyCUtensorMapType) {
1125	    PyErr_Format(PyExc_TypeError,
1126	                 "object must be of type PyCUtensorMap, got %s",
1127	                 Py_TYPE(obj)->tp_name);
1128	    return false;
1129	  }
1130	  *((CUtensorMap *)ptr) = ((PyCUtensorMapObject *)obj)->tensorMap;
1131	  // Depending on the cuda version, alignof(CUtensorMap) may be 64 or 128.
1132	  size_t alignment = alignof(CUtensorMap);
1133	  uintptr_t remainder = (uintptr_t)ptr & (alignment - 1);
1134	  if (remainder != 0) {
1135	    PyErr_Format(
1136	        PyExc_ValueError,
1137	        "CUtensorMap must be aligned to %ld, but got (&map) mod %ld = %ld",
1138	        alignment, alignment, remainder);
1139	    return false;
1140	  }
1141	  return true;
1142	}
