1146	#define MAX_NAMES_PER_EXTRACTOR 2
1147	
1148	typedef struct {
1149	  ExtractorFunc extract;
1150	  size_t size;
1151	  size_t alignment;
1152	  const char *name[MAX_NAMES_PER_EXTRACTOR];
1153	} Extractor;
