1155	typedef enum {
1156	  EXTRACTOR_UNKOWN_INDEX = 0,
1157	  // pointers
1158	  EXTRACTOR_POINTER_INDEX = 1,
1159	  // ints
1160	  EXTRACTOR_INT8_INDEX = 2,
1161	  EXTRACTOR_INT16_INDEX = 3,
1162	  EXTRACTOR_INT32_INDEX = 4,
1163	  EXTRACTOR_INT64_INDEX = 5,
1164	  // uints
1165	  EXTRACTOR_UINT8_INDEX = 6,
1166	  EXTRACTOR_UINT16_INDEX = 7,
1167	  EXTRACTOR_UINT32_INDEX = 8,
1168	  EXTRACTOR_UINT64_INDEX = 9,
1169	  // floats
1170	  EXTRACTOR_FP16_INDEX = 10,
1171	  EXTRACTOR_BF16_INDEX = 11,
1172	  EXTRACTOR_FP32_INDEX = 12,
1173	  EXTRACTOR_FP64_INDEX = 13,
1174	  // custom
1175	  EXTRACTOR_NVTMADESC_INDEX = 14,
1176	  // last entry to have a count
1177	  EXTRACTOR_TYPE_COUNT
1178	} ExtractorTypeIndex;
