1180	Extractor extraction_map[EXTRACTOR_TYPE_COUNT] = {
1181	    [EXTRACTOR_UNKOWN_INDEX] =
1182	        (Extractor){.extract = NULL, .size = 0, .name = NULL},
1183	    [EXTRACTOR_POINTER_INDEX] = (Extractor){.extract = extractPointer,
1184	                                            .size = sizeof(CUdeviceptr),
