1193	                                          .size = sizeof(int32_t),
1194	                                          .name = {"i1", "i32"}},
1195	    [EXTRACTOR_INT64_INDEX] = (Extractor){.extract = extractI64,
1196	                                          .size = sizeof(int64_t),
1197	                                          .name = {"i64"}},
1198	    [EXTRACTOR_UINT8_INDEX] = (Extractor){.extract = extractU8,
1199	                                          .size = sizeof(uint8_t),
1200	                                          .name = {"u8"}},
1201	    [EXTRACTOR_UINT16_INDEX] = (Extractor){.extract = extractU16,
1202	                                           .size = sizeof(uint16_t),
1203	                                           .name = {"u16"}},
1204	    [EXTRACTOR_UINT32_INDEX] = (Extractor){.extract = extractU32,
1205	                                           .size = sizeof(uint32_t),
1206	                                           .name = {"u1", "u32"}},
1207	    [EXTRACTOR_UINT64_INDEX] = (Extractor){.extract = extractU64,
1208	                                           .size = sizeof(uint64_t),
1209	                                           .name = {"u64"}},
1210	    [EXTRACTOR_FP16_INDEX] = (Extractor){.extract = extractFP16,
1211	                                         .size = sizeof(uint16_t),
1212	                                         .name = {"fp16"}},
1213	    [EXTRACTOR_BF16_INDEX] = (Extractor){.extract = extractBF16,
1214	                                         .size = sizeof(uint16_t),
1215	                                         .name = {"bf16"}},
1216	    [EXTRACTOR_FP32_INDEX] = (Extractor){.extract = extractFP32,
1217	                                         .size = sizeof(uint32_t),
1218	                                         .name = {"fp32", "f32"}},
1219	    [EXTRACTOR_FP64_INDEX] = (Extractor){.extract = extractFP64,
1220	                                         .size = sizeof(uint64_t),
