1228	Extractor getExtractor(uint8_t index) {
1229	  if (index >= EXTRACTOR_TYPE_COUNT) {
1230	    return extraction_map[EXTRACTOR_UNKOWN_INDEX];
1231	  }
1232	  return extraction_map[index];
1233	}
