1235	bool isMatch(const char *type_bytes, ExtractorTypeIndex idx) {
1236	  Extractor extractor = extraction_map[idx];
1237	  for (int j = 0; j < MAX_NAMES_PER_EXTRACTOR; j++) {
1238	    if (extractor.name[j] != NULL &&
1239	        strcmp(type_bytes, extractor.name[j]) == 0) {
1240	      return true;
1241	    }
1242	  }
1243	  return false;
1244	}
1245	
1246	ExtractorTypeIndex getExtractorIndex(PyObject *type) {
1247	  Py_ssize_t type_len = 0;
1248	  const char *type_bytes = PyUnicode_AsUTF8AndSize(type, &type_len);
1249	  if (!type_bytes) {
1250	    return EXTRACTOR_UNKOWN_INDEX;
1251	  }
1252	  if (type_len < 2) {
1253	    PyErr_Format(PyExc_RuntimeError, "Unexpected data type: %R", type);
1254	    return EXTRACTOR_UNKOWN_INDEX;
1255	  }
1256	  // Examples: '*fp32', 'fp32', 'i8', etc.
1257	  if (type_bytes[0] == '*') {
1258	    return EXTRACTOR_POINTER_INDEX;
1259	  }
1260	  for (ExtractorTypeIndex i = EXTRACTOR_INT8_INDEX; i < EXTRACTOR_TYPE_COUNT;
1261	       i++) {
1262	    if (isMatch(type_bytes, i)) {
1263	      return i;
1264	    }
1265	  }
1266	
1267	  PyErr_Format(PyExc_RuntimeError, "Unknown data type: %R", type);
1268	  return EXTRACTOR_UNKOWN_INDEX;
1269	}
