1271	// Takes in a list of types (ex: ['*fp32', 'u8', 'nvTmaDesc']) and returns
1272	// a bytes array that represent extractors for quick argument extraction
1273	// when launching.
1274	static PyObject *buildSignatureMetadata(PyObject *self, PyObject *args) {
1275	  PyObject *signature = NULL;
1276	  if (!PyArg_ParseTuple(args, "O", &signature)) {
1277	    return NULL;
1278	  }
1279	  PyObject *fast_signature = PySequence_Fast(
1280	      signature, "Expected kernel_arg_types to be a sequence or iterable");
1281	  if (!fast_signature) {
1282	    return NULL;
1283	  }
1284	  Py_ssize_t signature_size = PySequence_Fast_GET_SIZE(fast_signature);
1285	  PyObject **signature_items = PySequence_Fast_ITEMS(fast_signature);
1286	
1287	  // Create return bytes object.
1288	  PyObject *ret_bytes = PyBytes_FromStringAndSize(NULL, signature_size);
1289	  if (ret_bytes == NULL) {
1290	    Py_XDECREF(fast_signature);
1291	    return NULL;
1292	  }
1293	  char *buffer = PyBytes_AS_STRING(ret_bytes);
1294	  for (Py_ssize_t i = 0; i < signature_size; ++i) {
1295	    ExtractorTypeIndex extractor_idx = getExtractorIndex(signature_items[i]);
1296	    if (extractor_idx == EXTRACTOR_UNKOWN_INDEX) {
1297	      goto cleanup;
1298	    }
1299	    buffer[i] = (uint8_t)extractor_idx;
1300	  }
1301	
1302	  Py_XDECREF(fast_signature);
1303	  return ret_bytes;
1304	
1305	cleanup:
1306	  Py_XDECREF(fast_signature);
1307	  Py_XDECREF(ret_bytes);
1308	  return NULL;
1309	}
