1311	bool extractArgs(PyObject **final_list, int *list_idx, PyObject *kernel_args,
1312	                 PyObject *arg_annotations) {
1313	  // Extract arg annotations
1314	  PyObject *fast_annotations = PySequence_Fast(
1315	      arg_annotations, "Expected arg_annotations to be a sequence or iterable");
1316	  if (!fast_annotations) {
1317	    goto cleanup;
1318	  }
1319	  Py_ssize_t num_annotations = PySequence_Fast_GET_SIZE(fast_annotations);
1320	  PyObject **annotations = PySequence_Fast_ITEMS(fast_annotations);
1321	
1322	  PyObject *fast_args = PySequence_Fast(
1323	      kernel_args, "Expected kernel_args to be a sequence or iterable");
1324	  if (!fast_args) {
1325	    goto cleanup;
1326	  }
1327	  PyObject **args = PySequence_Fast_ITEMS(fast_args);
1328	
1329	  int arg_idx = 0;
1330	  for (int i = 0; i < num_annotations; ++i) {
1331	    PyKernelArgObject *annotation = (PyKernelArgObject *)annotations[i];
1332	    switch (annotation->type) {
1333	    case ARG_KERNEL:
1334	      final_list[(*list_idx)++] = args[arg_idx++];
1335	      break;
1336	    case ARG_TUPLE:
1337	      if (!extractArgs(final_list, list_idx, args[arg_idx++],
1338	                       annotation->nested_tuple)) {
1339	        goto cleanup;
1340	      }
1341	      break;
1342	    case ARG_CONSTEXPR:
1343	      arg_idx++;
1344	      break;
1345	    }
1346	  }
1347	  Py_DECREF(fast_annotations);
1348	  Py_DECREF(fast_args);
1349	  return true;
1350	
1351	cleanup:
1352	  Py_XDECREF(fast_annotations);
1353	  Py_XDECREF(fast_args);
1354	  return false;
1355	}
