1357	bool launchHook(PyObject *hook, PyObject *metadata) {
1358	  if (hook != Py_None) {
1359	    PyObject *ret = PyObject_CallOneArg(hook, metadata);
1360	    if (!ret) {
1361	      return false;
1362	    }
1363	    Py_DECREF(ret);
1364	  }
1365	  return true;
1366	}
