1368	static PyObject *launchKernel(PyObject *self, PyObject *args) {
1369	  // ensure cuda context is valid before calling any CUDA APIs, e.g. before
1370	  // calls to cuPointerGetAttributes
1371	  ensureCudaContext();
1372	
1373	  // Parse the arguments.
1374	  int gridX, gridY, gridZ;
1375	  uint64_t _stream;
1376	  uint64_t _function;
1377	  int launch_cooperative_grid;
1378	  int launch_pdl;
1379	  int num_warps, num_ctas, shared_memory;
1380	  PyObject *launch_metadata = NULL;
1381	  PyObject *launch_enter_hook = NULL;
1382	  PyObject *launch_exit_hook = NULL;
1383	  PyObject *global_scratch_obj = NULL;
1384	  PyObject *profile_scratch_obj = NULL;
1385	  PyObject *arg_annotations = NULL;
1386	  Py_buffer signature;
1387	  PyObject *kernel_args = NULL;
1388	  if (!PyArg_ParseTuple(args, "iiiKKpp(iii)OOOOOOy*O", &gridX, &gridY, &gridZ,
1389	                        &_stream, &_function, &launch_cooperative_grid,
1390	                        &launch_pdl, &num_warps, &num_ctas, &shared_memory,
1391	                        &launch_metadata, &launch_enter_hook, &launch_exit_hook,
1392	                        &global_scratch_obj, &profile_scratch_obj,
1393	                        &arg_annotations, &signature, &kernel_args)) {
1394	    return NULL;
1395	  }
1396	
1397	  // launch entry hook.
1398	  if (!launchHook(launch_enter_hook, launch_metadata)) {
1399	    goto cleanup;
1400	  }
1401	
1402	  uint8_t *extractor_data = (uint8_t *)signature.buf;
1403	  Py_ssize_t num_args = signature.len;
1404	
1405	  // Extract kernel parameters - flatten tuples & remove constexpr.
1406	  PyObject **args_data = (PyObject **)alloca(num_args * sizeof(PyObject *));
1407	  if (args_data == NULL) {
1408	    goto cleanup;
1409	  }
1410	  int list_idx = 0;
1411	  if (!extractArgs(args_data, &list_idx, kernel_args, arg_annotations)) {
1412	    goto cleanup;
1413	  }
1414	
1415	  // Number of parameters passed to kernel. + 2 for global & profile scratch.
1416	  int num_params = num_args + 2;
1417	  void **params = (void **)alloca(num_params * sizeof(void *));
1418	  int params_idx = 0;
1419	  // This loop has to stay in the same function that owns params, since we are
1420	  // using alloca to allocate pointers to it on the stack of the function.
1421	  for (Py_ssize_t i = 0; i < num_args; ++i) {
1422	    // Get extractor that will send back a struct with
1423	    // * size for allocation
1424	    // * function to call to put the parameter in params buffer
1425	    Extractor extractor = getExtractor(extractor_data[i]);
1426	    if (extractor.extract == NULL) {
1427	      goto cleanup;
1428	    }
1429	
1430	    size_t alignment = extractor.alignment;
1431	    if (alignment != 0) {
1432	      // Allocate enough space on the stack to guarantee an aligned block.
1433	      size_t size_with_alignment = extractor.size + alignment - 1;
1434	      void *storage_ptr = alloca(size_with_alignment);
1435	      void *aligned_ptr = (void *)((((uintptr_t)storage_ptr) + alignment - 1) &
1436	                                   ~(alignment - 1));
1437	      if (aligned_ptr == NULL) {
1438	        PyErr_SetString(PyExc_MemoryError, "Failed to align parameter storage");
1439	        goto cleanup;
1440	      }
1441	      params[params_idx] = aligned_ptr;
1442	    } else {
1443	      params[params_idx] = alloca(extractor.size);
1444	    }
1445	
1446	    PyObject *current_arg = args_data[i];
1447	    if (!extractor.extract(params[params_idx++], current_arg)) {
1448	      goto cleanup;
1449	    }
1450	  }
1451	  // Add scratch objects.
1452	  params[params_idx] = alloca(sizeof(void *));
1453	  if (!extractPointer(params[params_idx++], global_scratch_obj)) {
1454	    goto cleanup;
1455	  }
1456	  params[params_idx] = alloca(sizeof(void *));
1457	  if (!extractPointer(params[params_idx++], profile_scratch_obj)) {
1458	    goto cleanup;
1459	  }
1460	
1461	  Py_BEGIN_ALLOW_THREADS;
1462	  _launch(gridX, gridY, gridZ, num_warps, num_ctas, launch_cooperative_grid,
1463	          launch_pdl, shared_memory, (CUstream)_stream, (CUfunction)_function,
1464	          params);
1465	  Py_END_ALLOW_THREADS;
1466	  if (PyErr_Occurred()) {
1467	    goto cleanup;
1468	  }
1469	
1470	  if (!launchHook(launch_exit_hook, launch_metadata)) {
1471	    goto cleanup;
1472	  }
1473	  PyBuffer_Release(&signature);
1474	  Py_RETURN_NONE;
1475	
1476	cleanup:
1477	  PyBuffer_Release(&signature);
1478	  return NULL;
1479	}
